responses_query:
BEGIN; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
WITH recent AS MATERIALIZED (SELECT id,status_code,content,error_msg,timed_out,created FROM net._http_response ORDER BY id DESC LIMIT 150)
SELECT id,status_code,left(content,8000) content,error_msg,timed_out,created FROM recent WHERE content LIKE '%sample_requested%' OR content LIKE '%enrichment%' ORDER BY id DESC LIMIT 12; COMMIT;

checked_day_query:
BEGIN; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
WITH candidates AS MATERIALIZED (
 SELECT id FROM zoi.listings WHERE website IS NOT NULL AND website<>'' AND profile->'_enrich'->>'checked_at' >= '2026-10-15' ORDER BY profile->'_enrich'->>'checked_at',id LIMIT 2000
)
SELECT l.id,l.slug,l.name,l.website,l.profile#>>'{_enrich,checked_at}' checked_at,l.profile#>>'{_enrich,last_attempt_at}' last_attempt_at,l.profile#>>'{_enrich,status}' status,l.profile#>>'{_enrich,crawl_status}' crawl_status,l.profile#>>'{_enrich,last_error}' last_error,l.profile#>'{_enrich,source_identity}' source_identity,l.profile#>'{_enrich,brief}' brief,l.profile#>>'{_enrich,scope_review_required}' scope_review_required
FROM candidates c JOIN zoi.listings l ON l.id=c.id WHERE l.profile#>>'{_enrich,last_attempt_at}'>='2026-10-15T22:00' ORDER BY l.profile#>>'{_enrich,last_attempt_at}' LIMIT 12; COMMIT;

range_query:
BEGIN;SET LOCAL statement_timeout='5s';SET LOCAL lock_timeout='1s';
WITH ids AS MATERIALIZED(SELECT id FROM zoi.listings WHERE id>='12700000-0000-0000-0000-000000000000' AND id<'12a00000-0000-0000-0000-000000000000' ORDER BY id LIMIT 100)
SELECT l.id,l.slug,l.name,l.website,l.profile#>'{_enrich,client_brief}' client_brief,l.profile#>'{_enrich,provenance}' provenance,l.profile#>'{_enrich,source_identity}' source_identity,l.profile#>>'{_enrich,last_attempt_at}' attempted,l.profile#>>'{_enrich,status}' status,l.profile#>>'{_enrich,last_error}' error,l.profile#>'{_enrich,source_evidence}' source_evidence,(SELECT jsonb_agg(k) FROM jsonb_object_keys(coalesce(l.profile->'_enrich','{}'))k) machine_keys
FROM ids i JOIN zoi.listings l USING(id) WHERE l.profile#>>'{_enrich,last_attempt_at}'>='2026-10-15T22:00' ORDER BY l.id LIMIT 12;COMMIT;
